package com.sharehope.notification;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.net.*;import java.net.http.*;
@Service public class NotificationService{@Value("${app.brevo.api-key:}")String key;@Value("${app.notifications.admin-email:}")String admin;@Value("${app.notifications.sender-email:}")String sender;@Value("${app.public-url:https://www.sharehopeforall.org}")String site;public void sendAdminAlert(String subject,String adminPath){if(key.isBlank()||admin.isBlank()||sender.isBlank())return;try{String text="A new item is ready for review in the protected ShareHope admin portal: "+site+adminPath;String json="{\"sender\":{\"name\":\"ShareHope\",\"email\":\""+sender+"\"},\"to\":[{\"email\":\""+admin+"\"}],\"subject\":\""+subject+"\",\"textContent\":\""+text+"\"}";HttpRequest request=HttpRequest.newBuilder(URI.create("https://api.brevo.com/v3/smtp/email")).header("api-key",key).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(json)).build();HttpClient.newHttpClient().sendAsync(request,HttpResponse.BodyHandlers.discarding());}catch(Exception ignored){}}}
